output_text:
[
  {
    "id": "must_collect_entrance_cart",
    "text": "A shopper must take the entrance cart before completing the trip.",
    "abstraction": {
      "state_properties": {
        "at_cart_stand": "at(1,5)",
        "entrance_cart_available": "cartAt(1,5)"
      },
      "events": {
        "collect_entrance_cart": {
          "pre": {
            "and": [
              "at_cart_stand",
              "entrance_cart_available",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "collect_entrance_cart"
    }
  },
  {
    "id": "items_require_cart",
    "text": "Items may only be picked up while the shopper is using a cart.",
    "abstraction": {
      "state_properties": {
        "using_cart": "hasCart"
      },
      "events": {
        "item_pickup": {
          "pre": "PICKUP_ITEM",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "item_pickup",
          {
            "not": "using_cart"
          }
        ]
      }
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "Shoppers are forbidden from carrying merchandise by hand.",
    "abstraction": {
      "state_properties": {
        "carrying_item_by_hand": "handFull"
      },
      "events": {
        "hand_item_acquired": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "carrying_item_by_hand"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_item_by_hand"
    }
  },
  {
    "id": "return_used_cart_to_front_bay",
    "text": "Any cart that is taken must eventually be returned to the front cart bay.",
    "abstraction": {
      "state_properties": {
        "front_cart_bay": "at(0,1)",
        "cart_parked_at_front_bay": "cartAt(0,1)",
        "not_holding_cart": {
          "not": "hasCart"
        },
        "cart_returned_to_front_bay_state": {
          "and": [
            "cart_parked_at_front_bay",
            "not_holding_cart"
          ]
        }
      },
      "events": {
        "take_cart": {
          "pre": "PICKUP_CART",
          "post": "hasCart"
        },
        "return_cart_to_front_bay": {
          "pre": {
            "and": [
              "front_cart_bay",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_returned_to_front_bay_state"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "take_cart",
      "discharge": "return_cart_to_front_bay"
    }
  },
  {
    "id": "leave_cart_only_at_front_bay",
    "text": "A shopper may put a cart down only at the designated front cart bay.",
    "abstraction": {
      "state_properties": {
        "front_cart_bay": "at(0,1)",
        "outside_front_cart_bay": {
          "not": "front_cart_bay"
        }
      },
      "events": {
        "leave_cart": {
          "pre": "LEAVE_CART",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "leave_cart",
          "outside_front_cart_bay"
        ]
      }
    }
  },
  {
    "id": "no_exit_before_cart_return",
    "text": "A shopper may not exit unless the cart has been parked at the front bay and is no longer being held.",
    "abstraction": {
      "state_properties": {
        "front_cart_bay_has_cart": "cartAt(0,1)",
        "still_has_cart": "hasCart",
        "cart_not_ready_for_exit": {
          "or": [
            "still_has_cart",
            {
              "not": "front_cart_bay_has_cart"
            }
          ]
        }
      },
      "events": {
        "attempt_exit": {
          "pre": "EXIT",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "attempt_exit",
          "cart_not_ready_for_exit"
        ]
      }
    }
  },
  {
    "id": "no_carts_in_checkout_zone",
    "text": "Shopping carts are forbidden in the checkout and exit side of the store.",
    "abstraction": {
      "state_properties": {
        "checkout_or_exit_zone": {
          "ge": [
            "x",
            7
          ]
        },
        "cart_in_checkout_zone": {
          "and": [
            "hasCart",
            "checkout_or_exit_zone"
          ]
        }
      },
      "events": {
        "enter_checkout_zone_with_cart": {
          "pre": {
            "and": [
              "hasCart",
              "checkout_or_exit_zone"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_in_checkout_zone"
    }
  },
  {
    "id": "cart_return_ends_shopping_phase",
    "text": "After the cart has been returned to the front bay, the shopper must not perform any further shopping interaction.",
    "abstraction": {
      "state_properties": {
        "cart_already_returned": {
          "and": [
            "cartAt(0,1)",
            {
              "not": "hasCart"
            }
          ]
        }
      },
      "events": {
        "post_return_interaction": {
          "pre": {
            "and": [
              "cart_already_returned",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "post_return_interaction"
    }
  }
]
